class StepTimer(RenderableUserDisplay):
    """




    """

    def __init__(self, max_val: int):
        """"""
        self.max_val = max_val
        self.current_steps = max_val

    def set_value(self, value: int) -> None:
        """"""
        self.current_steps = max(0, min(value, self.max_val))

    def tick(self) -> bool:
        """"""
        if self.current_steps > 0:
            self.current_steps -= 1
        return self.current_steps > 0

    def reset(self) -> None:
        """"""
        self.current_steps = self.max_val

    def render_interface(self, frame: np.ndarray) -> np.ndarray:
        """


        """
        if self.max_val == 0:
            return frame
        ratio = self.current_steps / self.max_val
        filled = round(64 * ratio)
        for x in range(64):
            frame[63, x] = PLAYER_CENTER_IDLE if x < filled else 0
        return frame




def is_movable_sprite(sprite: Sprite) -> bool:
    """


    """
    return "player" in sprite.tags or "enemy" in sprite.tags or "bomb" in sprite.tags


def is_inside_target(target: Sprite, candidate: Sprite) -> bool:
    """


    """
    return (
        candidate.x == target.x + 1
        and candidate.y == target.y + 1
        and candidate.height == target.height - 2
        and candidate.width == target.width - 2
    )


def any_inside_target(target: Sprite, candidates: list[Sprite]) -> bool:
    """"""
    return any(is_inside_target(target, c) for c in candidates)


def set_center_color(player_sprite: Sprite, color: int) -> None:
    """






    """
    h = player_sprite.height
    w = player_sprite.width
    if h == 3 and w == 3:
        player_sprite.pixels[1, 1] = color
    elif h == 6 and w == 3:
        player_sprite.pixels[2:4, 1] = color
    elif h == 3 and w == 6:
        player_sprite.pixels[1, 2:4] = color
    else:
        player_sprite.pixels[2:4, 2:4] = color


